<?php /** @var array $privacy @var array $requests @var \Core\Security\Csrf $csrf */ $open=count(array_filter($requests,static fn($item)=>$item['status']!=='completed')); ?>
<section class="status-strip"><div class="status-chip <?= $privacy['banner_enabled']?'ok':'warn' ?>"><strong><?= $privacy['banner_enabled']?'On':'Off' ?></strong><span>Consent banner</span></div><div class="status-chip"><strong><?= e(strtoupper($privacy['provider'])) ?></strong><span>Analytics</span></div><div class="status-chip <?= $open?'warn':'ok' ?>"><strong><?= $open ?></strong><span>Open requests</span></div></section>
<div class="card"><div class="card-heading"><div><h2>Consent and analytics</h2><p class="card-subtitle">Analytics code is gated until a visitor explicitly allows it.</p></div><a class="btn secondary" href="<?= e_attr($basePath) ?>/privacy/request" target="_blank" rel="noopener">Open public request form</a></div><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="settings"><label class="choice-row"><input type="checkbox" name="banner_enabled" value="1" <?= $privacy['banner_enabled']?'checked':'' ?>><span><strong>Show cookie choice banner</strong><small>Visitors can accept or reject optional analytics before scripts load.</small></span></label><div class="inline-fields"><div><label>Analytics provider</label><select name="provider"><?php foreach(['none'=>'None','ga4'=>'Google Analytics 4','plausible'=>'Plausible'] as $v=>$l): ?><option value="<?= e_attr($v) ?>" <?= $privacy['provider']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></div><div><label>Measurement ID / domain</label><input name="site_id" value="<?= e_attr($privacy['site_id']) ?>" placeholder="G-XXXXXXXX or example.com"></div><button class="btn">Save privacy settings</button></div></form></div>
<div class="card"><div class="card-heading"><div><h2>Privacy requests</h2><p class="card-subtitle">Verify the requester’s identity outside this screen before providing or deleting data.</p></div><a class="btn small secondary" href="<?= e_attr($basePath) ?>/admin/privacy/export">Export CSV</a></div><?php if(!$requests): ?><div class="empty-state"><strong>No privacy requests</strong><span>Requests sent through the public privacy form will appear here.</span></div><?php else: ?><table><tr><th>Received</th><th>Request</th><th>Email / details</th><th>Status</th><th></th></tr><?php foreach($requests as $item): ?><tr><td><?= e($item['created_at']) ?></td><td><span class="badge neutral"><?= e(ucfirst($item['request_type'])) ?></span></td><td><strong><?= e($item['email']) ?></strong><br><span class="muted"><?= nl2br(e($item['details']??'')) ?></span></td><td><span class="badge <?= $item['status']==='completed'?'ok':'warn' ?>"><?= e(ucfirst($item['status'])) ?></span></td><td><?php if($item['status']!=='completed'): ?><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="complete"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="btn small" data-confirm="Mark this privacy request completed? Confirm identity verification and required action are already finished.">Mark completed</button></form><?php endif; ?></td></tr><?php endforeach; ?></table><?php endif; ?></div>
